import{_ as l,o as a,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph User Survey Working Group 2020-11-12","description":"","frontmatter":{"title":"Ceph User Survey Working Group 2020-11-12","date":"2020-11-12T00:00:00.000Z","updated":"2020-11-25T00:00:00.000Z","tags":["Ceph","用户调查","分布式存储","调查问卷"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_User_Survey_Working_Group_2020-11-12.md","filePath":"posts/2020/Ceph_User_Survey_Working_Group_2020-11-12.md","lastUpdated":1780460162000}'),o={name:"posts/2020/Ceph_User_Survey_Working_Group_2020-11-12.md"};function t(s,e,n,p,u,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议主要讨论了Ceph用户调查问卷的更新和改进。会议参与者包括Ceph研发人员和社区成员，共同审查了现有的调查问卷，并讨论了如何优化问题内容和调查界面。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>调查问卷链接分享与评论审查</strong>：</p><ul><li>参与者讨论了如何获取并分享包含调查结果的Google Docs链接。</li><li>审查了调查问卷中的评论，特别是关于2019年调查的问题。</li></ul></li><li><p><strong>问题内容和界面设计的讨论</strong>：</p><ul><li>讨论了如何改进调查问卷的问题内容，确保某些问题是多选而非单选。</li><li>讨论了调查界面的用户体验，如增加进度指示器和问题分类。</li></ul></li><li><p><strong>新问题的添加和旧问题的调整</strong>：</p><ul><li>讨论了添加新的问题，如关于CPU架构、存储设备使用情况、备份类型等。</li><li>讨论了调整现有问题，例如合并相关问题或删除不必要的问题。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>决定在Google Docs上继续添加和讨论评论，以进一步优化调查问卷。</li><li>计划在下一次会议前完成内容部分的准备工作，并讨论界面和导航的优化。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了调查问卷中某些问题需要调整为多选形式。</li><li>决定添加新的问题，如关于AMD CPU和存储设备形式的问题。</li><li>决定删除或合并一些重复或不必要的问题。</li><li>确定了增加调查进度指示器和问题分类的必要性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续在Google Docs上添加和讨论评论，优化调查问卷内容。</li><li>在下一次会议前完成内容部分的准备工作。</li><li>讨论和优化调查界面的用户体验，包括导航和问题呈现方式。</li><li>计划在假期前完成所有调查问卷的优化工作。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题并确定了后续行动计划后结束，预计在下一周继续进行相关讨论和优化工作。</p><p>在改进后的总结中，我确保保留了所有关键细节，包括会议的主要议题、决定的事项以及后续的行动计划。我还改进了原文的表述，使其更加流畅和清晰。</p>',12)])])}const c=l(o,[["render",t]]);export{d as __pageData,c as default};
